import { getSync } from "../..";
import { popupTutorialHTML } from "./html";
export async function showPopupTutorial() {
    try {
        const sync = await getSync();
        if (sync !== undefined) {
            if (sync.timers.popup_tutorial === null) {
                if (window.location.href.indexOf("adgone.org") > 0 ||
                    window.innerWidth < 600 ||
                    sync.trialDay > 2) {
                    return;
                }
                await chrome.runtime.sendMessage({
                    type: "popupTutorialShown",
                });
                const popupTutorial = document.createElement("div");
                popupTutorial.classList.add("popup-tutorial");
                popupTutorial.innerHTML = popupTutorialHTML;
                if (document.querySelector("body")) {
                    document.querySelector("body").append(popupTutorial);
                    const hasScrollBar = document.querySelector("body").scrollHeight >
                        window.innerHeight
                        ? true
                        : false;
                    if (!hasScrollBar) {
                        const baTutorialEl = document.querySelector(".ag-setup-widget");
                        baTutorialEl.style.right = "205px";
                    }
                    const popupTutorialClose = document.querySelector("#ag-setup-close span");
                    popupTutorialClose.addEventListener("click", async () => {
                        popupTutorial.style.display = "none";
                        await chrome.runtime.sendMessage({
                            type: "popupTutorialClosed",
                        });
                    });
                }
            }
        }
    }
    catch (error) {
        console.error(error);
    }
}
