"use strict";
import { handleAdGone } from "./lib/handlers/adgoneHandler";
import { handleFacebook } from "./lib/handlers/facebookHandler";
import { handleNative } from "./lib/handlers/nativeHandler";
import { handleYoutube } from "./lib/handlers/youtubeHandler";
import { showBanner } from "./lib/widgets/banner";
import { showBlockingTutorial, updateBlockingTutorial, } from "./lib/widgets/blockingTutorial";
import { showPopupTutorial } from "./lib/widgets/popupTutorial";
// * init
(async () => {
    await chrome.runtime.sendMessage({ type: "updateSiteBlockingStatus" });
    // * Handlers
    handleAdGone();
    handleFacebook();
    handleYoutube();
    handleNative();
    // * Widgets
    showBlockingTutorial();
    showPopupTutorial();
    showBanner();
    // * Right Click Menu
    const hostname = window.location.hostname.replace("www.", "");
    chrome.runtime.sendMessage({ type: "setAssetsForBlockingStatus" });
    chrome.runtime.sendMessage({ type: "setContextMenus" });
    // * Update Stats
    const isLoading = setInterval(async () => {
        if (/loaded|complete/.test(document.readyState)) {
            clearInterval(isLoading);
            await chrome.runtime.sendMessage({
                type: "getMatchedRules",
                hostname: hostname,
            });
            updateBlockingTutorial();
        }
    }, 10);
})();
