export function handleYoutube() {
    const observer = new MutationObserver(() => {
        try {
            if (document.getElementById("masthead-ad")) {
                chrome.runtime.sendMessage({ type: "csAdBlocked" });
                const mastHeadAd = document.getElementById("masthead-ad");
                mastHeadAd.parentNode.removeChild(mastHeadAd);
            }
            if (document.querySelectorAll("ytd-promoted-sparkles-web-renderer")
                .length > 0) {
                const sparkles = document.querySelectorAll("ytd-promoted-sparkles-web-renderer");
                sparkles.forEach((element) => {
                    chrome.runtime.sendMessage({ type: "csAdBlocked" });
                    element.parentNode.removeChild(element);
                });
            }
            if (document.querySelectorAll(".ytp-ad-image-overlay").length > 0) {
                const overlays = document.querySelectorAll(".ytp-ad-image-overlay");
                overlays.forEach((overlay) => {
                    chrome.runtime.sendMessage({ type: "csAdBlocked" });
                    overlay.parentNode.removeChild(overlay);
                });
            }
            if (document.getElementsByClassName("ytp-ad-skip-button").length > 0) {
                const skipButtons = document.querySelectorAll(".ytp-ad-skip-button");
                skipButtons.forEach((skipButton) => {
                    chrome.runtime.sendMessage({ type: "csAdBlocked" });
                    skipButton.click();
                });
            }
        }
        catch (error) {
            console.error(error);
        }
    });
    if (window.location.host.includes("youtube") &&
        document.querySelector("body")) {
        observer.observe(document.querySelector("body"), {
            attributes: true,
            childList: true,
            subtree: true,
        });
    }
}
