import { getSync } from "..";
function startEmailActivation(updateUser = false, oldUserId = null, email = null) {
    chrome.runtime.sendMessage({
        type: "startEmailActivation",
        updateUser: updateUser,
        oldUserId: oldUserId,
        email: email,
    });
}
function userPaymentUpdated() {
    chrome.runtime.sendMessage({ type: "userPaymentUpdated" });
}
function activate(sync) {
    const urlParams = new URLSearchParams(window.location.search);
    const pageParam = urlParams.get("pageType") || "";
    chrome.runtime.sendMessage({ type: "activate" }, () => {
        document.location.href =
            "https://adgone.org/adblocker/activated?user_id=" +
                sync.user_id +
                "&uc=" +
                sync.uc +
                "&source=" +
                sync.source +
                "&pageType=" +
                pageParam;
    });
}
export async function handleAdGone() {
    try {
        const sync = await getSync();
        if (sync !== undefined) {
            document.addEventListener("payment", function (_e) {
                activate(sync);
            });
            document.addEventListener("emailActivation", (e) => startEmailActivation(
            // @ts-ignore
            e.detail.updateUser, 
            // @ts-ignore
            e.detail.oldUserId, 
            // @ts-ignore
            e.detail.email));
            document.addEventListener("updatedPayment", () => userPaymentUpdated());
        }
    }
    catch (error) {
        console.error(error);
    }
}
