/**
 * Sets rules from config file (rules & whitelist urls)
 * Compares against current session rules and adds any
 * that don't exist.
 * @param rules chrome.declarativeNetRequest.Rule[]
 * @param whitelist string[]
 * @returns void
 */
export async function setSessionRules(rules, whitelist) {
    try {
        const currentRules = await chrome.declarativeNetRequest.getSessionRules();
        const rulesToAdd = [];
        let ruleId = currentRules.length + 1;
        rules.forEach((rule) => {
            let exists = false;
            if (currentRules.length) {
                currentRules.forEach((currentRule) => {
                    if (currentRule.condition.urlFilter.includes(rule.condition.urlFilter)) {
                        exists = true;
                    }
                });
            }
            if (!exists) {
                rule.id = ruleId;
                rulesToAdd.push(rule);
            }
            ruleId += 1;
        });
        whitelist.forEach(async (url) => {
            let exists = false;
            currentRules.forEach((currentRule) => {
                if (currentRule.condition.urlFilter.includes(url)) {
                    exists = true;
                }
            });
            if (!exists) {
                rulesToAdd.push({
                    id: ruleId,
                    priority: 1,
                    action: {
                        type: chrome.declarativeNetRequest.RuleActionType.ALLOW,
                    },
                    condition: {
                        urlFilter: url,
                        resourceTypes: [
                            chrome.declarativeNetRequest.ResourceType
                                .XMLHTTPREQUEST,
                        ],
                    },
                });
                ruleId += 1;
            }
        });
        await chrome.declarativeNetRequest.updateSessionRules({
            addRules: rulesToAdd,
        });
    }
    catch (error) {
        console.error(error);
    }
}
/**
 * Clears any dynamic rules that have been set by other extensions.
 * @returns True/False
 */
export async function clearDynamicRules() {
    try {
        const currentRules = await chrome.declarativeNetRequest.getDynamicRules();
        if (currentRules.length) {
            const ruleIds = Array.from(Array(currentRules.length).keys(), (n) => n + 1);
            await chrome.declarativeNetRequest.updateDynamicRules({
                removeRuleIds: ruleIds,
            });
            return true;
        }
        return false;
    }
    catch (error) {
        console.error(error);
    }
}
/**
 * Adds domains to the current whitelist
 * and creates/applies a rule for the domain.
 * @param urls string[]
 * @returns void
 */
export async function addToWhitelist(urls) {
    try {
        const sync = await getSync();
        if (sync !== undefined) {
            const currentRules = await chrome.declarativeNetRequest.getSessionRules();
            const rulesToRemove = [];
            const rulesToAdd = [];
            let ruleId = currentRules.length + 1;
            urls.forEach(async (url) => {
                const hostname = new URL(url).hostname.replace("www.", "");
                if (sync.whitelist.urls.includes(hostname)) {
                    return;
                }
                // Remove block filter if exists
                currentRules.forEach((rule) => {
                    if (rule.condition.urlFilter.includes(url)) {
                        rulesToRemove.push(rule.id);
                    }
                });
                // Add allow filter
                rulesToAdd.push({
                    id: ruleId,
                    priority: 1,
                    action: {
                        type: chrome.declarativeNetRequest.RuleActionType
                            .ALLOW_ALL_REQUESTS,
                    },
                    condition: {
                        urlFilter: hostname,
                        resourceTypes: [
                            chrome.declarativeNetRequest.ResourceType
                                .MAIN_FRAME,
                            chrome.declarativeNetRequest.ResourceType.SUB_FRAME,
                        ],
                    },
                });
                sync.whitelist.urls.push(hostname);
                ruleId += 1;
            });
            await chrome.declarativeNetRequest.updateSessionRules({
                removeRuleIds: rulesToRemove,
                addRules: rulesToAdd,
            });
            setPopupIconStatus(false);
            sync.siteBlockingEnabled = false;
            await saveSync(sync);
            reloadCurrentTab();
        }
    }
    catch (error) {
        console.error(error);
    }
}
/**
 * Removes a url from the whitelist and removes the associated rule.
 * @param urls string[]
 * @param rules chrome.declarativeNetRequest.Rule[]
 * @returns void
 */
export async function removeFromWhitelist(urls, rules) {
    try {
        const sync = await getSync();
        if (sync !== undefined) {
            const currentRules = await chrome.declarativeNetRequest.getSessionRules();
            const rulesToRemove = [];
            const rulesToAdd = [];
            let newRuleId = currentRules.length + 1;
            urls.forEach((url) => {
                const hostname = new URL(url).hostname.replace("www.", "");
                // Remove allow filter
                currentRules.forEach((rule) => {
                    if (rule.condition.urlFilter.includes(hostname)) {
                        rulesToRemove.push(rule.id);
                        sync.whitelist.urls.splice(sync.whitelist.urls.indexOf(hostname), 1);
                    }
                });
                // Add original block filter if exists
                rules.forEach((rule) => {
                    const urlFilter = rule.condition.urlFilter;
                    if (urlFilter.includes(url)) {
                        rule.id = newRuleId;
                        rulesToAdd.push(rule);
                        sync.whitelist.urls.push(urlFilter);
                        newRuleId += 1;
                    }
                });
            });
            await chrome.declarativeNetRequest.updateSessionRules({
                removeRuleIds: rulesToRemove,
                addRules: rulesToAdd,
            });
            setPopupIconStatus(true);
            sync.siteBlockingEnabled = true;
            await saveSync(sync);
            reloadCurrentTab();
        }
    }
    catch (error) {
        console.error(error);
    }
}
