/**
 * Reloads the current tab in the last focused browser window.
 * @returns void
 */
export async function reloadCurrentTab() {
    try {
        const [tab] = await chrome.tabs.query({
            active: true,
            lastFocusedWindow: true,
        });
        if (tab) {
            chrome.tabs.reload(tab.id);
        }
    }
    catch (err) {
        console.error(err);
    }
}
/**
 * Reloads all tabs in the last focused browser window.
 * @returns void
 */
export async function reloadAllTabs() {
    try {
        const tabs = await chrome.tabs.query({
            lastFocusedWindow: true,
        });
        if (tabs && tabs.length) {
            tabs.forEach((tab) => chrome.tabs.reload(tab.id));
        }
    }
    catch (err) {
        console.error(err);
    }
}
