/**
 * Determines the user's trial day based on their install date.
 * @returns Trial Day
 */
export async function getTrialDay(uc) {
    if (!uc) {
        try {
            const sync = await getSync();
            if (sync !== undefined) {
                uc = sync.uc;
            }
        }
        catch (error) {
            console.error(error);
        }
    }
    const difference = Math.abs(DateTime.fromISO(uc.toString()).toMillis() - DateTime.now().toMillis());
    const trialDay = Math.ceil(difference / (1000 * 60 * 60 * 24));
    console.log("trialDay", trialDay);
    return trialDay;
}
