/**
 * Formats the amount of time a user has saved with the extension.
 * @returns Time Stat
 */
export async function getStatsTime() {
    try {
        const sync = await getSync();
        if (sync !== undefined) {
            const savedMS = sync.stats.ads.total * 450;
            let timeSaved = "";
            await chrome.storage.sync.set({ sync });
            if (savedMS < 1000) {
                timeSaved = savedMS + " ms";
            }
            else if (savedMS < 60000) {
                timeSaved = savedMS / 1000 + " s";
            }
            else {
                timeSaved = Math.round(savedMS / 1000 / 60) + " min";
            }
            return timeSaved;
        }
    }
    catch (error) {
        console.error(error);
    }
}
