        const sync = await getSync();
        const url = "https://api.adgone.org/api/Validate?key=" +
            key +
            "&uc=" +
            sync.uc.toString() +
            "&user_id=" +
            sync.user_id;
        const response = await fetch(url);
        const data = await response.text();
        console.log("lib - activate - data", data);
