export function handleFacebook() {
    const observer = new MutationObserver(() => {
        try {
            const sideAds = document.getElementById("pagelet_ego_pane");
            if (sideAds) {
                sideAds.parentNode.removeChild(sideAds);
            }
            const feed = document.querySelectorAll('div[role="feed"] > div[data-pagelet^="FeedUnit"] > div[class]:not([style*="height"])');
            const hyperFeed = document.querySelectorAll('[id^="substream"] > div:not(.hidden_elem) div[id^="hyperfeed_story_id"]');
            const pagelets = feed.length > 0 ? feed : hyperFeed;
            pagelets.forEach((page) => {
                const pageStyle1 = page.querySelectorAll(".userContentWrapper h5 + div[data-testid] > span a > span > [class] [class]");
                const pageStyle2 = page.querySelectorAll(".userContentWrapper h5 + div[data-testid] > span > span [class] [class]");
                const pageStyle3 = page.querySelectorAll("a");
                const pageStyle = pageStyle1.length > pageStyle2.length
                    ? pageStyle1
                    : pageStyle2;
                if (page.querySelectorAll('div[aria-label="Sponsored"]')
                    .length > 0 ||
                    page.querySelectorAll('a[aria-label="Sponsored"]').length >
                        0) {
                    chrome.runtime.sendMessage({
                        type: "csblocked",
                        url: "facebook.com",
                    });
                    page.parentNode.removeChild(page);
                }
                if (pageStyle.length > 1) {
                    pageStyle3.forEach((p3El) => {
                        if (p3El.innerText === "Sponsored") {
                            chrome.runtime.sendMessage({
                                type: "csAdBlocked",
                            });
                            page.parentNode.removeChild(page);
                        }
                    });
                }
                let text = "";
                pageStyle.forEach((psEl) => {
                    if (psEl.classList.value.endsWith("-m")) {
                        text = text + psEl.innerText;
                    }
                });
                if (text === "Sponsored") {
                    chrome.runtime.sendMessage({ type: "csAdBlocked" });
                    page.parentNode.removeChild(page);
                }
                pageStyle3.forEach((ps3El) => {
                    if (ps3El.innerText === "Sponsored") {
                        chrome.runtime.sendMessage({ type: "csAdBlocked" });
                        page.parentNode.removeChild(page);
                    }
                });
            });
        }
        catch (error) {
            console.error(error);
        }
    });
    if (window.location.host.includes("facebook") &&
        document.querySelector("body")) {
        observer.observe(document.querySelector("body"), {
            attributes: true,
            childList: true,
            subtree: true,
        });
    }
}
