import { DateTime } from "luxon";
import { getSync, log, saveSync, setCookie } from ".";
import { PaddleStates } from "./sync";
/**
 * Async: Retreives subscription data from Paddle.
 * @param subscription_id
 * @param user_id
 * @param email
 * @param key
 * @param source
 * @returns Paddle Data
 */
async function getPaddleData(subscription_id, user_id, email, key, source) {
    try {
        const url = `https://api.adgone.org/api/getuserinfo?subscription_id=${subscription_id}&user_id=${user_id}&email=${email}&key=${key}&source=${source}`;
        const response = await fetch(url);
        const json = await response.json();
        return json;
    }
    catch (error) {
        if (error instanceof SyntaxError) {
            console.warn("LookupWarning: Paddle user not found");
        }
        else {
            console.error(error);
        }
    }
}
/**
 * Formats cookies from Paddle's data and saves them
 * with the setCookie function.
 * @param data
 */
function handlePaddleCookies(data) {
    if (data && Object.entries(data).length) {
        Object.entries(data).forEach(async (key, value) => {
            switch (key.toString()) {
                case "subscription_id":
                    await setCookie("AG_Sid", value.toString());
                    break;
                case "user_email":
                    await setCookie("AG_Email", value.toString());
                    break;
                case "state":
                    await setCookie("subscription_state", value.toString());
                    break;
                case "user_id":
                    await setCookie("paddle_user_id", value.toString());
                    break;
                case "update_url":
                case "cancel_url":
                case "signup_date":
                    await setCookie(key.toString(), value.toString().trim());
                    break;
                case "payment_information":
                    break;
                default:
                    await setCookie(key.toString(), JSON.stringify(value));
            }
        });
    }
}
/**
 * Updates paddle data in the sync object and updates sync storage.
 * @param result
 * @returns Paddle
 */
export async function setSyncPaddleData(result) {
    if (result !== null) {
        try {
            const sync = await getSync();
            if (sync) {
                if ((result.last_updated &&
                    DateTime.now().toMillis() - result.last_updated <
                        86400000) ||
                    !sync.hasPaid) {
                    // use previous paddle state to set popup
                    if (result.state === PaddleStates.past_due) {
                        await chrome.action.setPopup({
                            popup: "popupPastDue.html",
                        });
                    }
                    return;
                }
                const subscription_id = result.subscription_id
                    ? result.subscription_id
                    : "";
                const email = result.user_email
                    ? result.user_email
                    : "";
                const data = await getPaddleData(subscription_id, sync.user_id, email, sync.key, sync.source);
                if (data && Object.entries(data).length) {
                    data.last_updated = DateTime.now().toMillis();
                    if (sync.paddle.state &&
                        sync.paddle.state !== data.state) {
                        await log("ab_extension_state_update", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), sync.paddle.state + "~" + data.state);
                    }
                    if (data.state === PaddleStates.past_due) {
                        await chrome.browserAction.setPopup({
                            popup: "popupPastDue.html",
                        });
                    }
                    Object.assign(sync.paddle, data);
                    await saveSync(sync);
                    handlePaddleCookies(data);
                    return data;
                }
            }
        }
        catch (error) {
            console.error(error);
        }
    }
}
