import { log } from "../../index";
import { DateTime } from "luxon";
import { getSync } from "../..";
import { PaddleStates } from "../../sync";
import { bannerHTML, bannerPastDueHTML } from "./html";
export async function showBanner() {
    try {
        const sync = await getSync();
        if (sync !== undefined) {
            if (!sync.hasPaid && sync.schedule.banner.includes(sync.trialDay)) {
                if (sync.timers.banner &&
                    DateTime.now().toMillis() - sync.timers.banner < 86400000) {
                    return;
                }
                const isPastDue = sync.paddle &&
                    sync.paddle.state &&
                    sync.paddle.state === PaddleStates.past_due
                    ? true
                    : false;
                const banner = document.createElement("div");
                banner.classList.add("banner");
                banner.innerHTML = isPastDue ? bannerPastDueHTML : bannerHTML;
                if (document.querySelector("body")) {
                    document.querySelector("body").append(banner);
                    initBanner(isPastDue, sync);
                }
            }
        }
    }
    catch (error) {
        console.error(error);
    }
}
function initBanner(isPastDue = false, sync) {
    const agWidget = document.querySelector(".ag-widget");
    const agWidgetClose = document.querySelector("#ag-widget-close");
    if (!isPastDue) {
        const trialHeadingDate = document.querySelector(".ag-widget .ag-widget-heading h2 span");
        const trialHeadingH2 = document.querySelector(".ag-widget .ag-widget-heading h2");
        const agWidgetBtn = document.querySelector(".ag-widget .ag-widget-columns .ag-widget-column .ag-widget-btn");
        const statsColumnEl = document.querySelector(".ag-widget .ag-widget-columns .ag-widget-column:nth-child(2)");
        const benefitsColumnEl = document.querySelector(".ag-widget .ag-widget-columns .ag-widget-column:nth-child(3)");
        // First Trial
        if (!sync.hasPaid) {
            if (sync.trialDay <= 6) {
                trialHeadingDate.innerText = `${8 - sync.trialDay} Days`;
            }
            else if (sync.trialDay == 7) {
                trialHeadingDate.innerText = `${8 - sync.trialDay} Day`;
            }
            else if (sync.trialDay >= 29 && sync.trialDay < 35) {
                trialHeadingDate.parentElement.innerHTML = `<h2>Your Second Trial Expires In <span id="trial-time">${36 - sync.trialDay} Days</span>`;
                benefitsColumnEl.style.display = "none";
                statsColumnEl.style.display = "flex";
            }
            else if (sync.trialDay == 35) {
                trialHeadingDate.parentElement.innerHTML = `<h2>Your Second Trial Expires In <span id="trial-time">${36 - sync.trialDay} Day</span>`;
                benefitsColumnEl.style.display = "none";
                statsColumnEl.style.display = "flex";
                // Expired
            }
            else {
                agWidget.classList.add("expired");
                agWidgetBtn.classList.add("expired");
                trialHeadingH2.classList.add("expired");
                trialHeadingH2.innerText = "Your Trial Has Expired!";
            }
        }
        else if (sync.paddle.state &&
            (sync.paddle.state === PaddleStates.cancelled ||
                sync.paddle.state === PaddleStates.deleted)) {
            agWidget.classList.add("expired");
            agWidgetBtn.classList.add("expired");
            trialHeadingH2.classList.add("expired");
            trialHeadingH2.innerText = "Your Trial Has Expired!";
        }
        log("ab_bannerShown", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), "trialDay:" + sync.trialDay);
        agWidget.style.cursor = "pointer";
        agWidget.addEventListener("click", function (event) {
            // @ts-ignore
            if (!event.target.parentElement.id.includes("ag-widget-close")) {
                event.preventDefault();
                chrome.runtime.sendMessage({
                    type: "bannerClicked",
                });
                agWidget.style.display = "none";
            }
        });
        agWidgetClose.addEventListener("click", function () {
            agWidget.style.display = "none";
            chrome.runtime.sendMessage({
                type: "bannerClosed",
            });
        });
    }
    else {
        log("ab_pastDueBannerShown", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), "trialDay:" + sync.trialDay);
        agWidget.style.cursor = "pointer";
        agWidget.addEventListener("click", function (event) {
            // @ts-ignore
            if (!event.target.parentElement.id.includes("ag-widget-close")) {
                event.preventDefault();
                chrome.runtime.sendMessage({
                    type: "pastDueBannerClicked",
                    subscription_id: sync.paddle.subscription_id
                        ? sync.paddle.subscription_id
                        : "",
                });
                agWidget.style.display = "none";
            }
        });
        agWidgetClose.addEventListener("click", function () {
            agWidget.style.display = "none";
            chrome.runtime.sendMessage({
                type: "pastDueBannerClosed",
            });
        });
    }
    agWidget.style.display = "block";
    agWidget.style.animation = "slide-up 2s ease 0s 1 normal none";
}
