export const handleNative = () => {
    const observer = new MutationObserver(() => {
        const ads = [];
        ads.push(document.querySelectorAll(".native-ad-item"));
        ads.push(document.querySelectorAll(".dcmads"));
        ads.push(document.querySelectorAll(".bannersectionad"));
        ads.push(document.querySelectorAll(".adslabel"));
        ads.forEach((nodeList) => {
            nodeList.forEach((element) => {
                element.parentNode.removeChild(element);
                chrome.runtime.sendMessage({ type: "csAdBlocked" });
            });
        });
    });
    if (document.querySelector("body")) {
        observer.observe(document.querySelector("body"), {
            attributes: true,
            childList: true,
            subtree: true,
        });
    }
};
